<?php
require_once "functions.php"; requireRole("admin");
function existsAdmin($table,$id){global $conn;$id=(int)$id;$column=$table==="Predmet"?"id_predmet":"id_uporabnik";$s=$conn->prepare("SELECT 1 FROM $table WHERE $column=?");$s->execute([$id]);return (bool)$s->fetchColumn();}
if($_SERVER["REQUEST_METHOD"]==="POST"){
 $a=$_POST["action"]??"";
 try{
  if($a==="dodaj_predmet"){$conn->prepare("INSERT INTO Predmet(naziv,opis) VALUES(?,?)")->execute([trim($_POST["naziv"]),trim($_POST["opis"])]);flash("Predmet je bil dodan.");}
  elseif($a==="uredi_predmet"&&existsAdmin("Predmet",$_POST["id"])){$conn->prepare("UPDATE Predmet SET naziv=?,opis=? WHERE id_predmet=?")->execute([trim($_POST["naziv"]),trim($_POST["opis"]),(int)$_POST["id"]]);flash("Predmet je bil posodobljen.");}
  elseif($a==="izbrisi_predmet"&&existsAdmin("Predmet",$_POST["id"])){$id=(int)$_POST["id"];$conn->beginTransaction();$conn->prepare("DELETE FROM Oddana_Naloga WHERE naloga_id IN(SELECT id_naloga FROM Naloga WHERE predmet_id=?)")->execute([$id]);foreach(["Ucitelj_Predmet","Dijak_Predmet","Gradivo","Naloga","Ocena","Urnik"] as $t)$conn->prepare("DELETE FROM $t WHERE predmet_id=?")->execute([$id]);$conn->prepare("DELETE FROM Predmet WHERE id_predmet=?")->execute([$id]);$conn->commit();flash("Predmet in povezani zapisi so bili izbrisani.");}
  elseif($a==="dodaj_uporabnika"){$r=$_POST["vloga"]??"";if(!in_array($r,["ucitelj","dijak"],true))throw new RuntimeException("Neveljavna vloga.");$conn->prepare("INSERT INTO Uporabnik(ime,priimek,e_posta,geslo,vloga) VALUES(?,?,?,?,?)")->execute([trim($_POST["ime"]),trim($_POST["priimek"]),trim($_POST["e_posta"]),password_hash($_POST["geslo"],PASSWORD_DEFAULT),$r]);flash("Uporabnik je bil dodan.");}
  elseif($a==="uredi_uporabnika"&&existsAdmin("Uporabnik",$_POST["id"])){$r=$_POST["vloga"]??"";if(!in_array($r,["admin","ucitelj","dijak"],true))throw new RuntimeException("Neveljavna vloga.");$sql="UPDATE Uporabnik SET ime=?,priimek=?,e_posta=?,vloga=?";$v=[trim($_POST["ime"]),trim($_POST["priimek"]),trim($_POST["e_posta"]),$r];if($_POST["geslo"]!==""){$sql.=",geslo=?";$v[]=password_hash($_POST["geslo"],PASSWORD_DEFAULT);}$v[]=(int)$_POST["id"];$conn->prepare($sql." WHERE id_uporabnik=?")->execute($v);flash("Uporabnik je bil posodobljen.");}
  elseif($a==="izbrisi_uporabnika"&&existsAdmin("Uporabnik",$_POST["id"])){$id=(int)$_POST["id"];if($id===(int)$_SESSION["user_id"])throw new RuntimeException("Svojega računa ne morete izbrisati.");$conn->beginTransaction();$conn->prepare("DELETE FROM Oddana_Naloga WHERE dijak_id=? OR naloga_id IN(SELECT id_naloga FROM Naloga WHERE ucitelj_id=?)")->execute([$id,$id]);$conn->prepare("DELETE FROM Gradivo WHERE ucitelj_id=?")->execute([$id]);$conn->prepare("DELETE FROM Naloga WHERE ucitelj_id=?")->execute([$id]);$conn->prepare("DELETE FROM Ocena WHERE dijak_id=? OR ucitelj_id=?")->execute([$id,$id]);$conn->prepare("DELETE FROM Izostanek WHERE dijak_id=?")->execute([$id]);$conn->prepare("DELETE FROM Urnik WHERE ucitelj_id=?")->execute([$id]);$conn->prepare("DELETE FROM Ucitelj_Predmet WHERE ucitelj_id=?")->execute([$id]);$conn->prepare("DELETE FROM Dijak_Predmet WHERE dijak_id=?")->execute([$id]);$conn->prepare("DELETE FROM Uporabnik WHERE id_uporabnik=?")->execute([$id]);$conn->commit();flash("Uporabnik in povezani zapisi so bili izbrisani.");}
  elseif(in_array($a,["povezi_ucitelja","povezi_dijaka"],true)){$teacher=$a==="povezi_ucitelja";$col=$teacher?"ucitelj_id":"dijak_id";$table=$teacher?"Ucitelj_Predmet":"Dijak_Predmet";$id=(int)$_POST[$col];$s=$conn->prepare("SELECT 1 FROM Uporabnik WHERE id_uporabnik=? AND vloga=?");$s->execute([$id,$teacher?"ucitelj":"dijak"]);if(!$s->fetch()||!existsAdmin("Predmet",$_POST["predmet_id"]))throw new RuntimeException("Neveljaven uporabnik ali predmet.");$conn->prepare("INSERT INTO $table($col,predmet_id) VALUES(?,?)")->execute([$id,(int)$_POST["predmet_id"]]);flash("Povezava je bila dodana.");}
  elseif(in_array($a,["odstrani_ucitelja","odstrani_dijaka"],true)){$teacher=$a==="odstrani_ucitelja";$col=$teacher?"ucitelj_id":"dijak_id";$t=$teacher?"Ucitelj_Predmet":"Dijak_Predmet";$conn->prepare("DELETE FROM $t WHERE $col=? AND predmet_id=?")->execute([(int)$_POST[$col],(int)$_POST["predmet_id"]]);flash("Povezava je bila odstranjena.");}
 }catch(Throwable $e){if($conn->inTransaction())$conn->rollBack();flash("Napaka: ".($e instanceof PDOException?"preverite podatke ali podvojeno povezavo.":$e->getMessage()));}redirect("admin.php");
}
$predmeti=$conn->query("SELECT * FROM Predmet ORDER BY naziv")->fetchAll();$users=$conn->query("SELECT * FROM Uporabnik ORDER BY vloga,priimek,ime")->fetchAll();$ucitelji=array_filter($users,fn($u)=>$u["vloga"]==="ucitelj");$dijaki=array_filter($users,fn($u)=>$u["vloga"]==="dijak");
$up=$conn->query("SELECT u.id_uporabnik,u.ime,u.priimek,p.id_predmet,p.naziv FROM Ucitelj_Predmet x JOIN Uporabnik u ON u.id_uporabnik=x.ucitelj_id JOIN Predmet p ON p.id_predmet=x.predmet_id ORDER BY u.priimek,p.naziv")->fetchAll();$dp=$conn->query("SELECT u.id_uporabnik,u.ime,u.priimek,p.id_predmet,p.naziv FROM Dijak_Predmet x JOIN Uporabnik u ON u.id_uporabnik=x.dijak_id JOIN Predmet p ON p.id_predmet=x.predmet_id ORDER BY u.priimek,p.naziv")->fetchAll();pageStart("Administrator");
?>
<h1>Administrator</h1><div class="admin-grid"><section class="panel"><h2>Predmeti</h2><form method="post"><input type="hidden" name="action" value="dodaj_predmet"><input name="naziv" placeholder="Naziv predmeta" required><input name="opis" placeholder="Opis"><button class="btn blue">Dodaj</button></form><table><tr><th>Naziv</th><th>Opis</th><th></th><th></th></tr><?php foreach($predmeti as $p): ?><tr><form method="post"><input type="hidden" name="action" value="uredi_predmet"><input type="hidden" name="id" value="<?= $p["id_predmet"] ?>"><td><input name="naziv" value="<?=e($p["naziv"])?>" required></td><td><input name="opis" value="<?=e($p["opis"])?>"></td><td><button class="btn small">Shrani</button></td></form><td><form method="post"><input type="hidden" name="action" value="izbrisi_predmet"><input type="hidden" name="id" value="<?=$p["id_predmet"]?>"><button class="btn red small" onclick="return confirm('Izbrišem predmet in povezane zapise?')">Izbriši</button></form></td></tr><?php endforeach;?></table></section><section class="panel"><h2>Dodaj uporabnika</h2><form method="post"><input type="hidden" name="action" value="dodaj_uporabnika"><input name="ime" placeholder="Ime" required><input name="priimek" placeholder="Priimek" required><input type="email" name="e_posta" placeholder="E-pošta" required><input type="password" name="geslo" placeholder="Geslo" minlength="6" required><select name="vloga"><option value="ucitelj">Učitelj</option><option value="dijak">Dijak</option></select><button class="btn blue">Dodaj</button></form></section><section class="panel full"><h2>Uporabniki</h2><table><tr><th>Ime</th><th>Priimek</th><th>E-pošta</th><th>Vloga</th><th>Novo geslo</th><th></th><th></th></tr><?php foreach($users as $u):?><tr><form method="post"><input type="hidden" name="action" value="uredi_uporabnika"><input type="hidden" name="id" value="<?=$u["id_uporabnik"]?>"><td><input name="ime" value="<?=e($u["ime"])?>" required></td><td><input name="priimek" value="<?=e($u["priimek"])?>" required></td><td><input type="email" name="e_posta" value="<?=e($u["e_posta"])?>" required></td><td><select name="vloga"><?php foreach(["admin","ucitelj","dijak"] as $r):?><option value="<?=$r?>" <?=$u["vloga"]===$r?"selected":""?>><?=$r?></option><?php endforeach;?></select></td><td><input type="password" name="geslo" placeholder="Ne spremeni"></td><td><button class="btn small">Shrani</button></td></form><td><form method="post"><input type="hidden" name="action" value="izbrisi_uporabnika"><input type="hidden" name="id" value="<?=$u["id_uporabnik"]?>"><button class="btn red small" onclick="return confirm('Izbrišem uporabnika in povezane zapise?')">Izbriši</button></form></td></tr><?php endforeach;?></table></section><?php foreach([["Učitelj → predmet","povezi_ucitelja","odstrani_ucitelja","ucitelj_id",$ucitelji,$up],["Dijak → predmet","povezi_dijaka","odstrani_dijaka","dijak_id",$dijaki,$dp]] as $z):?><section class="panel"><h2><?=$z[0]?></h2><form method="post"><input type="hidden" name="action" value="<?=$z[1]?>"><select name="<?=$z[3]?>" required><option value="">Izberi uporabnika</option><?php foreach($z[4] as $u):?><option value="<?=$u["id_uporabnik"]?>"><?=e($u["priimek"]." ".$u["ime"])?></option><?php endforeach;?></select><select name="predmet_id" required><option value="">Izberi predmet</option><?php foreach($predmeti as $p):?><option value="<?=$p["id_predmet"]?>"><?=e($p["naziv"])?></option><?php endforeach;?></select><button class="btn blue">Poveži</button></form><?php foreach($z[5] as $x):?><div class="list-row"><span><?=e($x["priimek"]." ".$x["ime"]." — ".$x["naziv"])?></span><form method="post"><input type="hidden" name="action" value="<?=$z[2]?>"><input type="hidden" name="<?=$z[3]?>" value="<?=$x["id_uporabnik"]?>"><input type="hidden" name="predmet_id" value="<?=$x["id_predmet"]?>"><button class="btn red small">Odstrani</button></form></div><?php endforeach;?></section><?php endforeach;?></div><?php pageEnd();?>
